//! Internal notice models; schema validation occurs once at the decode boundary.
use anyhow::{Context as _, Result, bail};
use serde_json::{Value, json};
use std::fmt::Write as _;

pub fn models(schema: &Value) -> Result<(String, String)> {
    let closed = crate::notice_schema::closure(schema)?;
    let mut out = String::from(
        "// Generated by fractal-client-codegen; do not edit.\nuse serde::{Deserialize, Serialize};\n",
    );
    out.push_str(r##"
pub trait NoticeModel: serde::de::DeserializeOwned { const NAME: &'static str; }
pub fn decode_notice<T: NoticeModel>(value: serde_json::Value) -> anyhow::Result<T> {
    static VALIDATOR: std::sync::LazyLock<jsonschema::Validator> = std::sync::LazyLock::new(|| {
        let mut schema: serde_json::Value = serde_json::from_str(include_str!("notice_schema.generated.json")).expect("generated schema");
        let branches: Vec<_> = schema["$defs"].as_object().expect("definitions").keys()
            .filter(|name| name.starts_with("Notice"))
            .map(|name| serde_json::json!({"properties": {"model": {"const": name}, "value": {"$ref": format!("#/$defs/{name}")}}})).collect();
        schema["type"] = serde_json::json!("object");
        schema["required"] = serde_json::json!(["model", "value"]);
        schema["additionalProperties"] = serde_json::json!(false);
        schema["properties"] = serde_json::json!({"model": {}, "value": {}});
        schema["oneOf"] = serde_json::json!(branches);
        jsonschema::options().should_validate_formats(true).build(&schema).expect("supported notice schema")
    });
    let mut fields = serde_json::Map::new();
    fields.insert("model".into(), T::NAME.into());
    fields.insert("value".into(), value);
    let mut envelope = serde_json::Value::Object(fields);
    VALIDATOR.validate(&envelope).map_err(|error| anyhow::anyhow!(error.to_string()))?;
    Ok(serde_json::from_value(envelope["value"].take())?)
}
fn present<'de, D: serde::Deserializer<'de>, T: Deserialize<'de>>(d: D) -> Result<Option<T>, D::Error> {
    T::deserialize(d).map(Some)
}
"##);
    for (name, node) in &closed {
        emit(name, node, &mut out)?;
        if name.starts_with("Notice") {
            writeln!(
                out,
                "impl NoticeModel for {name} {{ const NAME: &'static str = {name:?}; }}"
            )?;
        }
    }
    Ok((
        out,
        serde_json::to_string_pretty(&json!({"$defs": closed}))? + "\n",
    ))
}

fn pascal(name: &str) -> String {
    name.split(['_', '-'])
        .map(|part| {
            let mut c = part.chars();
            c.next()
                .map(|first| first.to_uppercase().collect::<String>() + c.as_str())
                .unwrap_or_default()
        })
        .collect()
}

fn emit(name: &str, node: &Value, out: &mut String) -> Result<()> {
    if let Some(reference) = node["$ref"].as_str() {
        writeln!(
            out,
            "pub type {name} = {};",
            reference.strip_prefix("#/$defs/").context("local ref")?
        )?;
        return Ok(());
    }
    let mut nested = String::new();
    out.push_str("#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]\n");
    if let Some(branches) = node["oneOf"].as_array() {
        writeln!(out, "#[serde(untagged)] pub enum {name} {{")?;
        for (index, branch) in branches.iter().enumerate() {
            let child = format!("{name}Variant{index}");
            emit(&child, branch, &mut nested)?;
            writeln!(out, "Variant{index}({child}),")?;
        }
        out.push_str("}\n");
    } else if let Some(values) = node["enum"].as_array().map(Vec::as_slice).or_else(|| {
        node.get("const")
            .filter(|v| v.is_string())
            .map(std::slice::from_ref)
    }) {
        writeln!(out, "pub enum {name} {{")?;
        for value in values {
            let text = value.as_str().context("only string enums supported")?;
            writeln!(out, "#[serde(rename = {text:?})] {},", pascal(text))?;
        }
        out.push_str("}\n");
    } else if node["type"] == "object" {
        writeln!(out, "#[serde(deny_unknown_fields)] pub struct {name} {{")?;
        for (field, child) in node["properties"].as_object().context("properties")? {
            let child_name = format!("{name}{}", pascal(field));
            emit(&child_name, child, &mut nested)?;
            let required = node["required"]
                .as_array()
                .context("required")?
                .contains(&json!(field));
            let ty = if required {
                child_name
            } else {
                out.push_str("#[serde(default, deserialize_with = \"present\", skip_serializing_if = \"Option::is_none\")]\n");
                format!("Option<{child_name}>")
            };
            writeln!(out, "pub {field}: {ty},")?;
        }
        out.push_str("}\n");
    } else {
        let ty = match node["type"].as_str() {
            Some("string") => "String".to_owned(),
            Some("boolean") => "bool".to_owned(),
            Some("null") => "()".to_owned(),
            Some("array") => {
                let child = format!("{name}Item");
                emit(&child, &node["items"], &mut nested)?;
                format!("Vec<{child}>")
            }
            None if node["const"].is_u64() => "u64".to_owned(),
            _ => bail!("unsupported Rust notice type: {node}"),
        };
        writeln!(
            out,
            "#[serde(try_from = {ty:?})] pub struct {name}(pub {ty});\nimpl TryFrom<{ty}> for {name} {{ type Error = String; fn try_from(value: {ty}) -> Result<Self, String> {{"
        )?;
        for (keyword, op, length) in [
            ("minLength", ">=", "chars().count()"),
            ("maxLength", "<=", "chars().count()"),
            ("minItems", ">=", "len()"),
            ("maxItems", "<=", "len()"),
        ] {
            if let Some(bound) = node[keyword].as_u64() {
                if op == ">=" && bound == 1 {
                    writeln!(
                        out,
                        "if value.is_empty() {{ return Err({keyword:?}.into()); }}"
                    )?;
                } else {
                    check(out, &format!("value.{length} {op} {bound}"), keyword)?;
                }
            }
        }
        if let Some(constant) = node["const"].as_u64() {
            check(out, &format!("value == {constant}"), "constant")?;
        }
        if node["uniqueItems"] == true {
            check(
                out,
                "value.iter().collect::<std::collections::HashSet<_>>().len() == value.len()",
                "uniqueItems",
            )?;
        }
        if let Some(pattern) = node["pattern"].as_str() {
            pattern_check(out, pattern, "PATTERN")?;
        }
        match node["format"].as_str() {
            Some("date-time") => check(
                out,
                // jsonschema 0.33's private is_valid_time permits :60 only at UTC 23:59.
                "chrono::DateTime::parse_from_rfc3339(&value).is_ok_and(|instant| value.get(17..19) != Some(\"60\") || { let utc = instant.with_timezone(&chrono::Utc); chrono::Timelike::hour(&utc) == 23 && chrono::Timelike::minute(&utc) == 59 })",
                "date-time",
            )?,
            Some("uri-reference") => pattern_check(
                out,
                &super::rich::uri_reference_pattern().replace(r"$(?![\s\S])", r"\z"),
                "URI",
            )?,
            _ => (),
        }
        out.push_str("Ok(Self(value)) } }\n");
    }
    out.push_str(&nested);
    Ok(())
}

fn check(out: &mut String, condition: &str, label: &str) -> Result<()> {
    writeln!(out, "if !({condition}) {{ return Err({label:?}.into()); }}")?;
    Ok(())
}

fn pattern_check(out: &mut String, pattern: &str, name: &str) -> Result<()> {
    writeln!(
        out,
        "static {name}: std::sync::LazyLock<regex::Regex> = std::sync::LazyLock::new(|| regex::Regex::new({pattern:?}).expect(\"supported pattern\"));"
    )?;
    check(out, &format!("{name}.is_match(&value)"), "pattern")
}
